-- Degree planner: a catalog for each academic year.
--
-- Courses, credits and requirements follow the catalog of the year a student started, and they
-- change from one year to the next (the 2026-2027 Computer Science major drops CSC 265 and adds
-- SFE 331, for example). Every planner course and program now belongs to one catalog year, and
-- each year keeps its own copy, so a change to one year leaves the others as they were.
--
--   planner_catalogs  one row per catalog year ("2025-2026"), with its name and online catalog
--   planner_courses   + catalog_year; key (catalog_year, id). A course's requirements name
--                       courses of the same catalog year.
--   planner_degrees   + catalog_year; key (catalog_year, id). Also:
--                       kind          major, pre_engineering (a transfer program) or minor
--                       requirements  the catalog's list of what the program requires:
--                                     [{"options": [["CHM111", "CHM116"], ["CHM141"]]},
--                                      {"label": "Statistics Elective", "credits": 3,
--                                       "options": [["ECO212"], ["MTH204"], ["MTH401"]]},
--                                      {"label": "CSC or SFE Elective", "credits": 3}]
--                                     Met by all the courses of any one option. A requirement with
--                                     only a label (an elective, a core area) is the student's to fill.
--                       notes         the catalog's notes on the program
--   planner_plans     unchanged; a student's catalog year is part of their saved planner state.
--
-- The data section (generated from franciscan.smartcatalogiq.com) loads the 2022-2023 through
-- 2026-2027 undergraduate catalogs: majors, minors and pre-engineering programs, each with the
-- catalog's own semester-by-semester plan. Those replace the plans generated from prerequisites.
-- The existing courses and plans become the 2025-2026 catalog.

-- Catalog years ----------------------------------------------------------------------------------

create table public.planner_catalogs (
  year text primary key
    check (year ~ '^[0-9]{4}-[0-9]{4}$' and substr(year, 6, 4)::integer = substr(year, 1, 4)::integer + 1),
  name text not null check (char_length(name) between 1 and 200),
  catalog_url text check (catalog_url ~ '^https://[^ ]+$'),
  updated_at timestamptz not null default now()
);

comment on table public.planner_catalogs is
  'Catalog years for the degree planner. A student plans with the catalog of the year they started.';

create trigger set_updated_at before update on public.planner_catalogs
  for each row execute function private.set_updated_at();
create trigger audit_admin_edit after insert or update or delete on public.planner_catalogs
  for each row execute function private.audit_admin_edit();

alter table public.planner_catalogs enable row level security;
revoke all on public.planner_catalogs from anon, authenticated;
grant select on public.planner_catalogs to anon, authenticated;
grant insert, update, delete on public.planner_catalogs to authenticated;

create policy "Catalog years are public" on public.planner_catalogs for select to anon, authenticated using (true);
create policy "Admins manage catalog years" on public.planner_catalogs for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));

insert into public.planner_catalogs (year, name, catalog_url) values
  ('2022-2023', '2022-2023 Undergraduate Catalog', 'https://franciscan.smartcatalogiq.com/en/2022-2023/undergraduate-catalog'),
  ('2023-2024', '2023-2024 Undergraduate Catalog', 'https://franciscan.smartcatalogiq.com/en/2023-2024/undergraduate-catalog'),
  ('2024-2025', '2024-2025 Undergraduate Catalog', 'https://franciscan.smartcatalogiq.com/en/2024-2025/undergraduate-catalog-2024-2025'),
  ('2025-2026', '2025-2026 Undergraduate Catalog', 'https://franciscan.smartcatalogiq.com/en/2025-2026/undergraduate-catalog-2025-2026'),
  ('2026-2027', '2026-2027 Academic Catalog', 'https://franciscan.smartcatalogiq.com/en/2026-2027/academic-catalog-2026-2027');

-- Courses and programs belong to a catalog year -------------------------------------------------
-- Everything already here came from the 2025-2026 catalog.

alter table public.planner_courses
  add column catalog_year text not null default '2025-2026' references public.planner_catalogs (year);
alter table public.planner_courses alter column catalog_year drop default;
alter table public.planner_courses
  drop constraint planner_courses_pkey,
  drop constraint planner_courses_code_key,
  add primary key (catalog_year, id),
  add constraint planner_courses_code_key unique (catalog_year, code);

alter table public.planner_degrees
  add column catalog_year text not null default '2025-2026' references public.planner_catalogs (year),
  add column kind text not null default 'major' check (kind in ('major', 'pre_engineering', 'minor')),
  add column requirements jsonb not null default '[]'::jsonb
    check (jsonb_typeof(requirements) = 'array' and pg_column_size(requirements) < 50000),
  add column notes text[] not null default '{}' check (cardinality(notes) <= 40);
alter table public.planner_degrees alter column catalog_year drop default;
alter table public.planner_degrees
  drop constraint planner_degrees_pkey,
  add primary key (catalog_year, id);

comment on column public.planner_degrees.requirements is
  'What the program requires. Each item is met by all the courses of any one of its "options"; an item with only a "label" (an elective, a core area) is left to the student.';

-- Safeguards, now within a catalog year -----------------------------------------------------------

create or replace function private.check_planner_course()
returns trigger
language plpgsql set search_path = ''
as $$
declare
  grp jsonb;
begin
  if tg_op = 'UPDATE' and (new.id <> old.id or new.catalog_year <> old.catalog_year) then
    raise exception 'A course''s id and catalog year can''t change; add a new course instead' using errcode = '22023';
  end if;
  if jsonb_typeof(new.prerequisite_groups) <> 'array' or jsonb_array_length(new.prerequisite_groups) > 20 then
    raise exception 'prerequisite_groups must be a list of up to 20 groups' using errcode = '22023';
  end if;
  for grp in select value from jsonb_array_elements(new.prerequisite_groups) loop
    if jsonb_typeof(grp) <> 'object'
       or exists (select 1 from jsonb_object_keys(grp) k where k not in ('courses', 'other', 'concurrent'))
       or jsonb_typeof(grp -> 'courses') <> 'array'
       or jsonb_array_length(grp -> 'courses') not between 1 and 12
       or exists (select 1 from jsonb_array_elements(grp -> 'courses') c where jsonb_typeof(c) <> 'string')
       or (grp ? 'other' and (jsonb_typeof(grp -> 'other') <> 'string' or char_length(grp ->> 'other') not between 1 and 300))
       or (grp ? 'concurrent' and jsonb_typeof(grp -> 'concurrent') <> 'boolean') then
      raise exception 'Each prerequisite group needs "courses" (1 to 12 course ids), and may have "other" (text) and "concurrent" (true/false)'
        using errcode = '22023';
    end if;
  end loop;
  if jsonb_typeof(new.offered_years) <> 'object'
     or exists (select 1 from jsonb_each(new.offered_years) e
                where e.key not in ('fall', 'spring', 'summer')
                   or jsonb_typeof(e.value) <> 'string' or e.value #>> '{}' not in ('every', 'odd', 'even')) then
    raise exception 'offered_years maps fall, spring or summer to every, odd or even' using errcode = '22023';
  end if;
  return new;
end;
$$;

-- Runs when the transaction ends, so a batch of new courses can refer to each other.
create or replace function private.check_planner_course_refs()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  missing text;
begin
  if not exists (select 1 from public.planner_courses where catalog_year = new.catalog_year and id = new.id) then
    return null;  -- deleted again in the same transaction
  end if;
  select string_agg(ref, ', ') into missing
  from unnest(private.planner_course_refs(new.prerequisite_groups, new.corequisites)) ref
  where ref = new.id
     or not exists (select 1 from public.planner_courses c where c.catalog_year = new.catalog_year and c.id = ref);
  if missing is not null then
    raise exception '% (%) names courses that aren''t in its catalog, or itself: %', new.code, new.catalog_year, missing
      using errcode = '23503';
  end if;
  -- A loop of hard prerequisites (one course, no alternatives) could never be met.
  if exists (
    with recursive needs(id) as (
      select jsonb_array_elements_text(g -> 'courses')
      from jsonb_array_elements(new.prerequisite_groups) g
      where jsonb_array_length(g -> 'courses') = 1 and not g ? 'other' and not coalesce((g ->> 'concurrent')::boolean, false)
      union
      select jsonb_array_elements_text(g -> 'courses')
      from needs n
      join public.planner_courses c on c.catalog_year = new.catalog_year and c.id = n.id
      cross join lateral jsonb_array_elements(c.prerequisite_groups) g
      where jsonb_array_length(g -> 'courses') = 1 and not g ? 'other' and not coalesce((g ->> 'concurrent')::boolean, false)
    )
    select 1 from needs where id = new.id
  ) then
    raise exception '% would end up requiring itself through its prerequisites', new.code using errcode = '23514';
  end if;
  return null;
end;
$$;

-- The course ids a program's suggested plan and requirements name.
create function private.planner_degree_courses(semesters jsonb, requirements jsonb)
returns text[]
language sql immutable set search_path = ''
as $$
  select coalesce(array_agg(distinct ref), '{}')
  from (
    select e ->> 'course' as ref
    from jsonb_array_elements(semesters) s, jsonb_array_elements(s -> 'entries') e
    where e ? 'course'
    union all
    select jsonb_array_elements_text(o)
    from jsonb_array_elements(requirements) r, jsonb_array_elements(coalesce(r -> 'options', '[]')) o
  ) refs
$$;

-- A course other courses or a program of the same catalog year still use can't be deleted.
create or replace function private.guard_planner_course_delete()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  used_by text;
begin
  select string_agg(label, ', ') into used_by from (
    select c.code as label from public.planner_courses c
    where c.catalog_year = old.catalog_year and c.id <> old.id
      and old.id = any (private.planner_course_refs(c.prerequisite_groups, c.corequisites))
    union all
    select d.name from public.planner_degrees d
    where d.catalog_year = old.catalog_year and old.id = any (private.planner_degree_courses(d.semesters, d.requirements))
  ) uses;
  if used_by is not null then
    raise exception '% (%) is still used by: %. Remove it there first.', old.code, old.catalog_year, used_by
      using errcode = '23503';
  end if;
  return old;
end;
$$;

create or replace function private.check_planner_degree()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  sem jsonb;
  entry jsonb;
  req jsonb;
  missing text;
begin
  if tg_op = 'UPDATE' and (new.id <> old.id or new.catalog_year <> old.catalog_year) then
    raise exception 'A program''s id and catalog year can''t change' using errcode = '22023';
  end if;
  if jsonb_typeof(new.semesters) <> 'array' then
    raise exception 'semesters must be a list' using errcode = '22023';
  end if;
  for sem in select value from jsonb_array_elements(new.semesters) loop
    if jsonb_typeof(sem) <> 'object'
       or jsonb_typeof(sem -> 'year') <> 'number' or (sem ->> 'year')::numeric not between 1 and 8
       or sem ->> 'term' not in ('Fall', 'Spring', 'Summer')
       or (sem ? 'note' and jsonb_typeof(sem -> 'note') not in ('string', 'null'))
       or jsonb_typeof(sem -> 'entries') <> 'array' then
      raise exception 'Each semester needs a year (1 to 8), a term (Fall, Spring or Summer) and a list of entries'
        using errcode = '22023';
    end if;
    for entry in select value from jsonb_array_elements(sem -> 'entries') loop
      if not (
        (entry ? 'course' and jsonb_typeof(entry -> 'course') = 'string' and not entry ? 'slot')
        or (entry ? 'slot' and jsonb_typeof(entry -> 'slot') = 'string' and char_length(entry ->> 'slot') between 1 and 100
            and jsonb_typeof(entry -> 'credits') = 'number' and (entry ->> 'credits')::numeric between 0 and 20)
      ) then
        raise exception 'Each entry is either {"course": id} or {"slot": name, "credits": 0 to 20}' using errcode = '22023';
      end if;
    end loop;
  end loop;

  for req in select value from jsonb_array_elements(new.requirements) loop
    if jsonb_typeof(req) <> 'object'
       or exists (select 1 from jsonb_object_keys(req) k where k not in ('label', 'credits', 'options'))
       or not (req ? 'label' or req ? 'options')
       or (req ? 'label' and (jsonb_typeof(req -> 'label') <> 'string' or char_length(req ->> 'label') not between 1 and 200))
       or (req ? 'credits' and (jsonb_typeof(req -> 'credits') <> 'number' or (req ->> 'credits')::numeric not between 0 and 60))
       or (req ? 'options' and (
            case when jsonb_typeof(req -> 'options') = 'array' then jsonb_array_length(req -> 'options') else 0 end
              not between 1 and 20
            or exists (
              select 1 from jsonb_array_elements(case when jsonb_typeof(req -> 'options') = 'array' then req -> 'options' end) o
              where case when jsonb_typeof(o) = 'array' then jsonb_array_length(o) else 0 end not between 1 and 12
                 or exists (select 1 from jsonb_array_elements(case when jsonb_typeof(o) = 'array' then o end) c
                            where jsonb_typeof(c) <> 'string')))) then
      raise exception 'Each requirement has "options" (lists of course ids; any one list meets it), a "label", or both, and may have "credits"'
        using errcode = '22023';
    end if;
  end loop;

  if exists (select 1 from unnest(new.notes) n where n is null or char_length(n) not between 1 and 2000) then
    raise exception 'Each note is 1 to 2000 characters' using errcode = '22023';
  end if;

  select string_agg(ref, ', ') into missing
  from unnest(private.planner_degree_courses(new.semesters, new.requirements)) ref
  where not exists (select 1 from public.planner_courses c where c.catalog_year = new.catalog_year and c.id = ref);
  if missing is not null then
    raise exception 'The % program (%) names courses that aren''t in its catalog: %', new.name, new.catalog_year, missing
      using errcode = '23503';
  end if;
  return new;
end;
$$;

drop trigger check_planner_degree on public.planner_degrees;
create trigger check_planner_degree before insert or update of id, catalog_year, semesters, requirements, notes
  on public.planner_degrees for each row execute function private.check_planner_degree();

-- Checking the suggested plans, per catalog year ----------------------------------------------------

drop function public.planner_catalog_issues();

-- One row per problem: catalog year, program, the semester's position (0 = the first fall), the
-- course, and what's wrong. course_id is null for problems with a whole semester or plan.
create function public.planner_catalog_issues()
returns table (catalog_year text, degree_id text, semester_index integer, course_id text, issue text)
language sql stable security invoker set search_path = ''
as $$
  with entries as (
    select d.catalog_year, d.id as degree_id, d.total_credits, (s.ord - 1)::integer as idx, s.value ->> 'term' as term,
           e.value ->> 'course' as course_id, coalesce(c.credits, (e.value ->> 'credits')::integer, 0) as credits
    from public.planner_degrees d
    cross join lateral jsonb_array_elements(d.semesters) with ordinality s(value, ord)
    cross join lateral jsonb_array_elements(s.value -> 'entries') e(value)
    left join public.planner_courses c on c.catalog_year = d.catalog_year and c.id = e.value ->> 'course'
  ),
  courses as (
    select e.*, c.code, c.prerequisite_groups, c.corequisites, c.offered, c.offered_years
    from entries e join public.planner_courses c on c.catalog_year = e.catalog_year and c.id = e.course_id
  )
  -- Prerequisite groups that nothing earlier (or alongside, when allowed) meets.
  select x.catalog_year, x.degree_id, x.idx, x.course_id,
         'Needs ' || (select string_agg(coalesce(pc.code, r), ' or ')
                      from jsonb_array_elements_text(g -> 'courses') r
                      left join public.planner_courses pc on pc.catalog_year = x.catalog_year and pc.id = r) || ' first'
  from courses x
  cross join lateral jsonb_array_elements(x.prerequisite_groups) g
  where not g ? 'other'
    and not exists (
      select 1 from entries y
      where y.catalog_year = x.catalog_year and y.degree_id = x.degree_id
        and y.course_id in (select jsonb_array_elements_text(g -> 'courses'))
        and (y.idx < x.idx or (y.idx = x.idx and coalesce((g ->> 'concurrent')::boolean, false))))
  union all
  -- Corequisites that aren't planned in the same or an earlier term.
  select x.catalog_year, x.degree_id, x.idx, x.course_id, 'Take with ' || coalesce(cc.code, r)
  from courses x
  cross join lateral unnest(x.corequisites) r
  left join public.planner_courses cc on cc.catalog_year = x.catalog_year and cc.id = r
  where not exists (select 1 from entries y
                    where y.catalog_year = x.catalog_year and y.degree_id = x.degree_id and y.course_id = r and y.idx <= x.idx)
  union all
  -- Courses placed in a term they aren't offered.
  select x.catalog_year, x.degree_id, x.idx, x.course_id, 'Only offered in ' || array_to_string(x.offered, ' and ')
  from courses x
  where cardinality(x.offered) > 0 and lower(x.term) <> all (x.offered)
  union all
  -- Courses offered only in odd or even years, placed in the other kind. The plan starts in the
  -- fall of the catalog year (semester 0 is fall 2025 for 2025-2026).
  select x.catalog_year, x.degree_id, x.idx, x.course_id,
         'Only offered in ' || (x.offered_years ->> lower(x.term)) || ' years (' || lower(x.term) || ' '
           || (substr(x.catalog_year, 1, 4)::integer + x.idx / 2 + x.idx % 2) || ' is not)'
  from courses x
  where x.offered_years ->> lower(x.term) in ('odd', 'even')
    and ((substr(x.catalog_year, 1, 4)::integer + x.idx / 2 + x.idx % 2) % 2 = 1) <> (x.offered_years ->> lower(x.term) = 'odd')
  union all
  -- Semesters over 18 credits.
  select e.catalog_year, e.degree_id, e.idx, null, 'Semester has ' || sum(e.credits) || ' credits (over 18)'
  from entries e group by e.catalog_year, e.degree_id, e.idx having sum(e.credits) > 18
  union all
  -- Plans whose credits don't add up to the program's total.
  select e.catalog_year, e.degree_id, null, null,
         'Plan adds up to ' || sum(e.credits) || ' credits; the program needs ' || max(e.total_credits)
  from entries e group by e.catalog_year, e.degree_id having sum(e.credits) <> max(e.total_credits)
  order by 1, 2, 3 nulls first, 4
$$;

comment on function public.planner_catalog_issues() is
  'Problems in the suggested plans of every catalog year: prerequisites not met earlier, corequisites not alongside, terms or years not offered, credit totals.';

revoke execute on function public.planner_catalog_issues() from public;
grant execute on function public.planner_catalog_issues() to anon, authenticated, service_role;

revoke execute on function private.planner_degree_courses(jsonb, jsonb) from public, anon, authenticated, service_role;

-- The admin-edit audit names the catalog year of planner rows ---------------------------------------

create or replace function private.log_admin_edit(tbl text, op text, before_row jsonb, after_row jsonb)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  ident text;
  changes jsonb;
  row_now jsonb := coalesce(after_row, before_row);
begin
  if not (private.is_admin() or current_setting('role', true) = 'service_role') then
    return;
  end if;
  ident := row_now ->> coalesce(
    (select k from unnest(array['id', 'key', 'user_id', 'year']) k where row_now ? k limit 1), 'id');

  select coalesce(jsonb_object_agg(k, jsonb_build_object(
           'from', private.audit_clip(before_row -> k), 'to', private.audit_clip(after_row -> k))), '{}')
  into changes
  from jsonb_object_keys(row_now) k
  where k not in ('updated_at', 'created_at', 'search')
    and not (tbl = 'profiles' and k = 'role')  -- role changes have their own entry
    and (op <> 'UPDATE' or before_row -> k is distinct from after_row -> k);

  if op = 'UPDATE' and changes = '{}'::jsonb then
    return;
  end if;

  perform private.audit(
    case op when 'INSERT' then 'admin_created' when 'UPDATE' then 'admin_edited' else 'admin_deleted' end,
    tbl,
    case when ident ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then ident::uuid end,
    jsonb_build_object('key', ident, 'changes', changes)
      || case when tbl <> 'planner_catalogs' and row_now ? 'catalog_year'
              then jsonb_build_object('catalog_year', row_now ->> 'catalog_year') else '{}'::jsonb end
  );
end;
$$;

-- Catalog data -------------------------------------------------------------------------------------
-- Generated from each year's undergraduate catalog on franciscan.smartcatalogiq.com: course pages
-- (title, credits, requirements, when offered) and program pages (requirements, notes and the
-- semester-by-semester plan). Requirements are read the same way as the 2025-2026 import
-- (20261015700000); a few sentences were set by hand from the same wording, which is stored
-- alongside for students to read. Courses a year's catalog doesn't list aren't in that year.


