  name = excluded.name, degree = excluded.degree, kind = excluded.kind, total_credits = excluded.total_credits,
  catalog_url = excluded.catalog_url, auto_generated = false, sort_order = excluded.sort_order,
  semesters = excluded.semesters, requirements = excluded.requirements, notes = excluded.notes;

